/**
 * MS PAGOS (NestJS / TypeORM / PostgreSQL)
 * Datos de prueba SmartTex (generados con un unico script, IDs fijos compartidos entre microservicios)
 *  * Usuarios: 1 Gerente (id 1), 3 Vendedores (ids 2-4), 2 Operadores (ids 5-6), 50 Clientes (ids 7-56)
 *  * Roles: 1=Cliente 2=Operador 3=Vendedor 4=Gerente
 *  * Estados venta: COMPLETADA / CANCELADA / PENDIENTE   |   reserva: CONFIRMADO / LIBERADO / RESERVADO
 *  * reserva.id == venta.id  y  reserva_unidades_rollos replica el detalle_venta de cada venta
 *  * Datos de Stripe simulados (cus_/pm_/pi_ NO existen en Stripe)
 * Requisito: las tablas ya existen (arranca la app una vez con synchronize o corre tus migraciones).
 * Ejecutar:  npx ts-node src/seeds/seed.ts   (o: npx tsx src/seeds/seed.ts)
 * id_venta / id_usuario son FK blandas: coinciden con los IDs del seeder de Laravel.
 */
import 'dotenv/config'; 

import { DataSource, QueryRunner } from 'typeorm';
// Importa tus entidades (ajusta la ruta según tus carpetas)
import { Tarjeta } from './infrastructure/entities/tarjeta.entity';
import { Pago } from './infrastructure/entities/pago.entity';
import { Factura } from './infrastructure/entities/factura.entity';

const dataSource = new DataSource({
  type: 'postgres',
  host: process.env.DB_HOST,
  port: Number(process.env.DB_PORT),
  username: process.env.DB_USER,
  
  // 2. CORREGIDO: Tu variable en el .env se llama DB_PASSWORD
  password: process.env.DB_PASSWORD, 
  database: process.env.DB_NAME,
  
  // 3. CRÍTICO PARA NEON: Encender SSL
  ssl: {
    rejectUnauthorized: false,
  },
  
  // 4. Debes decirle al DataSource qué tablas existen
  entities: [Tarjeta, Pago, Factura],
});

type Row = (string | number | null)[];

/** Inserta por lotes con parametros; ON CONFLICT permite volver a correr el seed sin duplicar. */
async function bulk(qr: QueryRunner, table: string, columns: string[], rows: Row[]): Promise<void> {
  const perChunk = Math.floor(30000 / columns.length);
  for (let i = 0; i < rows.length; i += perChunk) {
    const params: (string | number | null)[] = [];
    const values = rows
      .slice(i, i + perChunk)
      .map((r) => '(' + r.map((v) => { params.push(v); return `$${params.length}`; }).join(',') + ')')
      .join(',');
    await qr.query(
      `INSERT INTO ${table} (${columns.join(',')}) VALUES ${values} ON CONFLICT (id) DO NOTHING`,
      params,
    );
  }
}

async function syncSequence(qr: QueryRunner, table: string): Promise<void> {
  await qr.query(
    `SELECT setval(pg_get_serial_sequence('${table}', 'id'), COALESCE((SELECT MAX(id) FROM ${table}), 1))`,
  );
}

